import Foundation

// Shared-heap transport for admitted canonical modules. Each completed result
// carries the original EAX independently of the native safety diagnostics.
// This does not supply missing game services or establish gameplay integration.
final class ClawNativeCanonicalHost {
    // MARK: - Completion and fault transport

    enum Diagnostic: String, Codable, Equatable {
        case unknownEntry
        case unsupportedABI
        case recursiveCanonicalCall
        case invalidStackFrame
        case canonicalDepthExceeded
        case missingDependency
        case invalidMemorySpan
        case nativeFault
    }
    struct Fault: Codable, Equatable {
        let code: UInt32
        let address: UInt32
        let diagnostic: Diagnostic
    }
    struct Completion: Equatable {
        let completed: Bool
        let eax: UInt32?
        let fault: Fault?
    }
    // The dependency owns its exact address/ABI checks. nil means unsupported;
    // zero is a legitimate original return. The full envelope is passed by value
    // without conversion to the narrower legacy SceneActorCall.
    typealias Dependency = (ClawNativeCanonicalHost, ClawCall) -> UInt32?

    let heap: ClawTokenHeap
    var dependency: Dependency?
    // Read-only witness of every validated native-level call in order, before
    // canonical precedence or the dependency decides its owner.
    var observer: ((ClawCall) -> Void)?
    // Copied machine output after the finite TownGuard source return. Like
    // entry observation, this hook cannot reenter or change pinned ownership.
    var townSourceObserver: ((UInt32, ClawSourceContext) -> Void)?
    // Bytes below a stackless caller's entry ESP left for its own locals when
    // it nests a canonical callee. nil (the default) rejects such nesting.
    var stacklessCallerReserve: UInt32?
    private let native = UnsafeMutablePointer<ClawHost>.allocate(capacity: 1)
    private static let stackSize = Int(CLAW_STACK_END - CLAW_STACK_BASE)
    private let stack = UnsafeMutablePointer<UInt8>.allocate(capacity: stackSize)
    // The ordinary compatibility API exposes raw borrowed stack aliases.
    // Source graph memory is disjoint and never exposed through public bytes.
    private let sourceStack = UnsafeMutablePointer<UInt8>.allocate(capacity: stackSize)
    private let remainingOperations = UnsafeMutablePointer<UInt64>.allocate(capacity: 1)
    private var diagnostic: Diagnostic?
    private var frames: [UInt32] = []
    // Closed callback/constructor/vtable election. Never infer direction from
    // interchangeable virtual targets or from mutable helper bytes.

    // MARK: - Object dispatch identities

    private enum TowerKind: UInt32 {
        // Skull root CALL/continuation metadata (ordinary canonical bodies
        // expose no PC; identity/phase elect these original joins):
        // new 48a835 -> 48a83a, constructor 48a850 -> 48a855,
        // slot +10 48a867 -> 48a86a, +20 48a874 -> 48a877,
        // lifecycle 48a889 -> 48a88e, +1c 48a898 -> 48a89b.
        // The constructor is 48a8c0; vtable 50f744 retains its true owners.
        case left = 0x495d40, right = 0x495e00, skull = 0x48a800
        var constructor: UInt32 { self == .skull ? 0x48a8c0 : self == .left ? 0x495ec0 : 0x495f90 }
        var vtable: UInt32 { self == .skull ? 0x50f744 : self == .left ? 0x50fa64 : 0x50fa8c }
        var allocationReturn: UInt32 { self == .skull ? 0x48a83a : self == .left ? 0x495d7a : 0x495e3a }
    }
