    // Physical callers supply incoming CW/SW/TOP/live slots; the canonical
    // exact shim checks each descendant's entry and final publication.
    private var objectX87Environment: ClawX87State?
    func withObjectX87Environment<T>(_ initial: ClawX87State, body: () -> T) -> (T, ClawX87State)? {
        var initial=initial
        guard fault==nil,frames.isEmpty,activeGraph==nil,objectX87Environment==nil,
              claw_canonical_x87_state_ok(&initial)==1,initial.control==0x023f,initial.popCount==0,initial.pushCount==0,
              initial.returned==0,initial.eax==0,initial.edx==0 else {_=contextReject(0x44c000);return nil}
        objectX87Environment=initial
        defer {objectX87Environment=nil}
        let value=body()
        guard fault==nil,let output=objectX87Environment else {return nil}
        return (value,output)
    }
