    struct CrtAllocationWitness {
        let token: UInt32, requested: UInt32, capacity: UInt32
        let generation: UInt64
        let identity: ClawTokenHeap.AllocationIdentity
    }
    // Optional composition adapter, avoiding a dependency on the concrete CRT
    // allocator in standalone MFC hosts. The adapter is the live CRT provider.
    protocol SourceSharedStorage: AnyObject {
        var sharedHeap: ClawTokenHeap { get }
        var sharedSectionOwner: ClawNativePhysicalSections? { get }
        func sharedMalloc(_ count: UInt32) throws -> UInt32
        func sharedAllocation(_ token: UInt32) throws -> CrtAllocationWitness
        func sharedFree(_ token: UInt32) throws
    }
    protocol SourceCrtProvider: AnyObject {
        func validCrtBinding(for host: ClawNativeCanonicalHost) -> Bool
        func crtImportTarget(_ slot: UInt32) -> UInt32?
        func serviceSourceCrt(_ request: SourceCrtRequest) -> UInt32?
        func crtAllocationWitness(_ token: UInt32) -> CrtAllocationWitness?
    }
    struct SourceCrtRequest {
        let function: UInt32, target: UInt32, returnPC: UInt32
        let arguments: [UInt32], context: ClawSourceContext, stack: Data
        private final class Lease {
            weak var host: ClawNativeCanonicalHost?
            weak var graph: SourceGraph?
            weak var provider: SourceCrtProvider?
            let thread = pthread_self()
            var active = true, consumed = false
            var allocation: CrtAllocationWitness?
            var sourcePointer: UnsafeMutablePointer<ClawSourceContext>?
            var sourceContext: ClawSourceContext?
            init(_ host: ClawNativeCanonicalHost, _ graph: SourceGraph, _ provider: SourceCrtProvider) {
                self.host = host; self.graph = graph; self.provider = provider
            }
