              UInt64(token)+UInt64(count)<=UInt64(CLAW_STACK_BASE) || token>=CLAW_STACK_END,
              let identity=heap.containingAllocationIdentity(at:token,count:count) else { return false }
        if let prior=graph.applicationSpans[token] {
            guard prior.identity === identity else { return false }
            graph.applicationSpans[token]=(max(prior.count,count),identity)
        } else { graph.applicationSpans[token]=(count,identity) }
        return true
    }
    private func boundedStringSize(_ token: UInt32) -> UInt32? {
        guard token != 0 else { return nil }
        for count in 1...UInt32(1<<20) {
            guard UInt64(token)+UInt64(count)<=UInt32.max,let byte=heap.lookupBytes(token+count-1,count:1) else { return nil }
            if byte[0]==0 { return count }
        }
        return nil
    }
    struct TLSInteriorOwner: Codable, Equatable {
        let address: UInt32, size: UInt32, allocation: UInt32, allocationSize: UInt32, identity: UInt32, offset: UInt32
    }
    struct ModuleSnapshot: Equatable {
        let tls: TLSSnapshot, locks: LocksSnapshot
        let sourceGlobalBytes: [String: [UInt8]]
        var interiorOwners: [TLSInteriorOwner] = []
        var applicationBytes: [String: [UInt8]] = [:]
    }
    struct ModuleObservation {
        let function: UInt32, returnPC: UInt32, arguments: [UInt32], physical: Bool
        let input: ClawSourceContext, stackBefore: Data, before: ModuleSnapshot, order: Int
        var output: ClawSourceContext?, stackAfter: Data?, after: ModuleSnapshot?, returnOrder: Int?
        var completed = false
    }
    private func moduleSnapshot(_ graph: SourceGraph) -> ModuleSnapshot? {
        guard let memory = graph.moduleProvider, let locks = graph.locksProvider else { return nil }
        var globals: [String: [UInt8]] = [:]
        // The two physical owners use adjacent spans for locks and TLS storage.
        for (base, count) in [(UInt32(0x53ec9c),8),(0x5408e0,0x244)] {
            var bytes: [UInt8] = []
            for offset in 0..<count {
                guard let p = heap.lookupBytes(base + UInt32(offset), count: 1) else { return nil }
                bytes.append(p[0])
            }
            globals[String(base)] = bytes
        }
        return .init(tls: memory.tlsSnapshot(), locks: locks.locksSnapshot(), sourceGlobalBytes: globals, interiorOwners: memory.applicationTLSOwnerSnapshot(), applicationBytes: graph.applicationProvider?.applicationBytes() ?? [:])
    }
    private func moduleBegin(_ graph: SourceGraph, function: UInt32, pc: UInt32, arguments: [UInt32], context: ClawSourceContext, physical: Bool) -> Int? {
        if (graph.staticApplicationFrame != nil || graph.listOwnedFrame != nil) {
            guard materializeThreadHead(graph,fsHead:context.fsHead,at:function),
                  crtObserve(graph,function:function,target:physical ? context.eip : function,pc:pc,arguments:arguments,
                             context:context,physical:physical,returning:false,completed:false,moduleBoundary:true) else {
                if graph.staticFaultPrefix==nil { graph.staticFaultPrefix=context }
                return nil
            }
        }
        guard let snapshot = moduleSnapshot(graph) else { return nil }
        let index = graph.moduleObservations.count
        graph.moduleObservations.append(.init(function: function, returnPC: pc, arguments: arguments, physical: physical,
            input: context, stackBefore: Data(bytes: sourceStack, count: Self.stackSize), before: snapshot, order: graph.moduleOrder))
        graph.moduleOrder += 1; return index
    }
    private func moduleEnd(_ graph: SourceGraph, _ index: Int?, context: ClawSourceContext, completed: Bool) {
        if (graph.staticApplicationFrame != nil || graph.listOwnedFrame != nil) {
            _=materializeThreadHead(graph,fsHead:context.fsHead,at:context.eip,executedFaultPrefix:fault != nil)
        }
        guard let index else { return }
        if (graph.staticApplicationFrame != nil || graph.listOwnedFrame != nil) {
            let entry=graph.moduleObservations[index]
            _=crtObserve(graph,function:entry.function,target:entry.physical ? entry.input.eip : entry.function,
                         pc:entry.returnPC,arguments:entry.arguments,context:context,
                         physical:entry.physical,returning:true,completed:completed && fault==nil,moduleBoundary:true)
        }
        graph.moduleObservations[index].output = context
        graph.moduleObservations[index].stackAfter = Data(bytes: sourceStack, count: Self.stackSize)
        graph.moduleObservations[index].after = moduleSnapshot(graph)
        graph.moduleObservations[index].completed = completed && fault == nil
        graph.moduleObservations[index].returnOrder = graph.moduleOrder; graph.moduleOrder += 1
    }
    struct TLSObservation {
        fileprivate var moduleIndex: Int?
        let function: UInt32, returnPC: UInt32, arguments: [UInt32]
        let input: ClawSourceContext, stackBefore: Data, before: TLSSnapshot
        var output: ClawSourceContext?, stackAfter: Data?, after: TLSSnapshot?
        var completed = false
    }
    func withTLSSourceGraph<T>(provider: SourceTLSProvider, body: (SourceGraph) -> T) -> T? {
        guard provider.validTLSBinding(for: self), let allocator = SourceLocalAllocator(host: self, provider: provider) else {
            _ = contextReject(0x50335e); return nil
        }
        return withSourceGraph(localAllocator: allocator, managerProvider: provider) { graph in
            graph.tlsProvider = provider
            defer { graph.tlsProvider = nil; graph.tlsOwnedFactory = nil }
            return body(graph)
        }
    }
    // A single lifetime owns the complete module graph and both physical services.
    // The Memory owner must carry the exact Locks instance selected at creation.
    func withModuleSourceGraph<T>(provider: SourceModuleProvider, body: (SourceGraph) -> T) -> T? {
        guard provider.validTLSBinding(for: self), provider.ownsModuleSingleton(),
              provider.ownsTLSOwner(0x53ec9c), let locks = provider.moduleLocks,
              locks.validLocksBinding(for: self),
              let allocator = SourceLocalAllocator(host: self, provider: provider) else {
            _ = contextReject(0x50228f); return nil
        }
        return withSourceGraph(localAllocator: allocator, managerProvider: provider) { graph in
            graph.tlsProvider = provider; graph.locksProvider = locks; graph.moduleProvider = provider
            defer {
                graph.moduleProvider = nil; graph.moduleAllocations.removeAll()
                graph.tlsProvider = nil; graph.locksProvider = nil; graph.tlsOwnedFactory = nil
            }
            return body(graph)
        }
    }
    private static let finalReceiverSpans: [(UInt32,UInt32)] = [(0x540878,108),(0x541348,20),(0x541378,20),(0x544b18,24),(0x544b50,24),(0x544b68,24),(0x544b80,24),(0x544e80,4),(0x5345a0,24),(0x540b48,20)]
    private func validFinalSpan(_ graph: SourceGraph, at address: UInt32, count: UInt32) -> Bool {
        guard let span=graph.stringFrontierSpans[address],span.count>=count else { return false }
        return heap.containingAllocationIdentity(at:address,count:count) === span.identity
    }
    private func validFinalGUIReceiver(_ graph: SourceGraph) -> Bool {
        validFinalSpan(graph,at:0x540878,count:108)
    }
    private func validModule(_ graph: SourceGraph) -> Bool {
        if graph.finalStaticRecords {
            guard Self.finalReceiverSpans.allSatisfy({ validFinalSpan(graph,at:$0.0,count:$0.1) }),let platform=graph.crtProvider as? SourceFinalPlatformProvider,platform.finalPlatformReady else { return false }
            let tokens=platform.finalPhysicalIdentities
            guard Set(tokens).count==tokens.count,tokens.allSatisfy({ $0>0xffff && !($0>=CLAW_STACK_BASE && $0<CLAW_STACK_END) && !heap.overlaps($0,count:1) }),
                  graph.managerProvider?.managerSnapshot().blocks.allSatisfy({ !tokens.contains($0.handle) }) ?? true else { return false }
        }
        guard graph.memoryThrowSpans.allSatisfy({ heap.containingAllocationIdentity(at:$0.key,count:$0.value.0) === $0.value.1 }),
              graph.memoryThrowReadonly.allSatisfy({ base,expected in
                  heap.lookupBytes(base,count:UInt32(expected.count)).map { Data(bytes:$0,count:expected.count)==expected } == true
              }) else { return false }
        if let head=graph.threadHeadBinding,
           heap.containingAllocationIdentity(at:head.address,count:4) !== head.identity ||
               heap.lookup(head.address,words:1)?[0] != head.value { return false }
        if let identity=graph.staticLockIdentity, heap.containingAllocationIdentity(at:0x540708,count:60) !== identity { return false }
        if let identity=graph.staticTableIdentity, heap.containingAllocationIdentity(at:0x522000,count:4) !== identity { return false }
        if let expected=graph.staticTableExpected {
            guard heap.containingAllocationIdentity(at:0x522000,count:UInt32(expected.count)*4) === graph.staticTableIdentity,
                  expected.enumerated().allSatisfy({ heap.lookup(0x522000+UInt32($0.offset)*4,words:1)?[0]==$0.element }) else { return false }
        }
        if let identity=graph.staticRangeIdentity, heap.containingAllocationIdentity(at:0x534820,count:36) !== identity { return false }
        if let provider = graph.crtProvider, !provider.validCrtBinding(for: self) { return false }
        guard graph.staticReadonlyBytes.allSatisfy({ base,expected in
                  guard let bytes=heap.lookupBytes(base,count:UInt32(expected.count)) else { return false }
                  return Data(bytes:bytes,count:expected.count)==expected
              }),graph.stringFrontierSpans.allSatisfy({ heap.containingAllocationIdentity(at:$0.key,count:$0.value.count) === $0.value.identity }),
              graph.rangeReceiverSpans.allSatisfy({ heap.containingAllocationIdentity(at:$0.key,count:36) === $0.value }),
              graph.rangeGlobalSpans.allSatisfy({ heap.containingAllocationIdentity(at:$0.key,count:$0.value.count) === $0.value.identity }),
              graph.rangeAllocations.values.allSatisfy({ prior in
                  guard let current=graph.crtProvider?.crtAllocationWitness(prior.token) else { return false }
                  return current.token==prior.token && current.requested==prior.requested && current.capacity==prior.capacity &&
                      current.generation==prior.generation && current.identity === prior.identity &&
                      heap.allocationIdentity(at:prior.token,count:prior.capacity) === prior.identity
              }) else { return false }
        if let application = graph.applicationProvider {
            guard application.validApplicationBinding(for: self), graph.applicationSpans.allSatisfy({ token, span in
                heap.containingAllocationIdentity(at: token, count: span.count) === span.identity
            }) else { return false }
        }
        guard let provider = graph.moduleProvider else { return true }
        return provider.validTLSBinding(for: self) && provider.ownsModuleSingleton() &&
            provider.ownsTLSOwner(0x53ec9c) && provider.moduleLocks === graph.locksProvider &&
            graph.locksProvider?.validLocksBinding(for: self) == true &&
            (graph.applicationModule.map { provider.ownsApplicationTLSOwner($0) } ?? true) &&
            graph.moduleAllocations.allSatisfy { token, witness in
                guard provider.ownsSourceLocal(token,count:witness.count),
                      heap.allocationIdentity(at:token,count:witness.capacity) === witness.identity else { return false }
                if let generation=witness.generation {
                    guard let live=graph.crtProvider?.crtAllocationWitness(token) else { return false }
                    return live.token==token && live.requested==witness.count && live.capacity==witness.capacity &&
                        live.generation==generation && live.identity === witness.identity
                }
                return witness.capacity==witness.count
            }
    }
    private func retainModuleAllocation(_ graph: SourceGraph, token: UInt32, count: UInt32) -> Bool {
        guard let provider=graph.moduleProvider,provider.ownsSourceLocal(token,count:count) else { return false }
        let capacity:UInt32,identity:ClawTokenHeap.AllocationIdentity,generation:UInt64?
        if let crt=graph.crtProvider {
            // The joint owner reserves rounded physical capacity. Source extent
            // stays requested bytes; the lease binds both plus real generation.
            guard let live=crt.crtAllocationWitness(token),live.token==token,live.requested==count,
                  heap.allocationIdentity(at:token,count:live.capacity) === live.identity else { return false }
            capacity=live.capacity;identity=live.identity;generation=live.generation
        } else {
            guard let exact=heap.allocationIdentity(at:token,count:count) else { return false }
            capacity=count;identity=exact;generation=nil
        }
        if let prior=graph.moduleAllocations[token] {
            return prior.count==count && prior.capacity==capacity && prior.generation==generation && prior.identity === identity
        }
        graph.moduleAllocations[token]=(count,identity,capacity,generation);return true
    }
    // Physical owner hooks share one reentrancy barrier, including cross-owner calls.
    private var physicalServiceActive = false
    var physicalServiceInProgress: Bool { physicalServiceActive }
    var snapshotQuiescent: Bool {
        !physicalServiceActive && frames.isEmpty && activeGraph == nil && ordinaryEntries.isEmpty &&
        contextEntries.isEmpty && objectX87Environment == nil && objectAllocationProvider == nil && objectAudioProvider == nil &&
        objectNewFrame == nil && towerSourceFrame == nil && !towerSourceChild && !towerExternalService &&
        punkRatRetirement == nil && punkRatChildRetirement == nil && punkRatBindings.isEmpty && punkRatChildren.isEmpty &&
        hermitRetirement == nil && fishRetirement == nil && seagullRetirement == nil && townRetirement == nil &&
        skullRetirement == nil && jumpSwitchRetirement == nil && aquatisRetirement == nil &&
        stalactiteRetirement == nil && redTailWindRetirement == nil && conveyorStringFrame == nil &&
        windDebrisSpawn == nil && !aquatisDynamiteUpdating && !crtObservationActive &&
        townSourceFrames.isEmpty && seagullSourceFrame == nil && omarRetiringChild == nil &&
        omarTemporaryCallerFrame == nil && redTailBossTemporaryCallerFrame == nil &&
        mercatBaseConstructorFrame == nil && parrotCallerFrame == nil &&
        aquatisAuthorized == nil && stalactiteAuthorized == nil && redTailWindAuthorized == nil
    }
    var snapshotBindingInventory: [String: Int] {
        ["punkRat":punkRatBindings.count,"punkRat.children":punkRatChildren.count,"tower": towerBindings.count, "logic": towerLogicBindings.count, "plank": plankBindings.count,
         "town": townBindings.count, "hermit": hermitBindings.count, "fish": fishBindings.count,
         "seagull": seagullBindings.count, "path": pathElevatorBindings.count,
         "skull.resources": skullResources.count, "conveyor.strings": conveyorStrings.count,
         "aquatis": aquatisBindings.count, "stalactite": stalactiteBindings.count,
         "wind": redTailWindBindings.count, "wind.audio": windAudioRamps.count]
    }

    // Closed graph names assigned by the scene factory, never process addresses.
    // The registry borrows providers: Memory owns its host, so retaining Memory
    // here would create a cycle and extend allocation authority past teardown.

    // MARK: - Snapshot bindings

    enum SnapshotProviderKey: String, Codable, Hashable { case towerCannonLeft, towerCannonRight }
    private struct SnapshotProvider { weak var value: ObjectAllocationProvider? }
    private var snapshotProviders: [SnapshotProviderKey: SnapshotProvider] = [:]
    func registerSnapshotProvider(_ provider: ObjectAllocationProvider, key: SnapshotProviderKey) throws {
        guard snapshotQuiescent else { throw ClawSnapshotError.activeFrame }
        guard provider.validObjectAllocationBinding(for: self),
              snapshotProviders[key]?.value == nil || snapshotProviders[key]?.value === provider,
              !snapshotProviders.contains(where: { $0.key != key && $0.value.value === provider })
        else { throw ClawSnapshotError.invalidState }
        snapshotProviders[key] = SnapshotProvider(value: provider)
    }
    private func snapshotProviderKey(_ identity: ObjectIdentifier) throws -> SnapshotProviderKey {
        guard let key = snapshotProviders.first(where: { $0.value.value.map(ObjectIdentifier.init) == identity })?.key
        else { throw ClawSnapshotError.incompleteOwners }
        return key
    }

    struct BindingsSavedState: Codable, Equatable {
        struct Tower: Codable, Equatable {
            let kind: UInt32, provider: SnapshotProviderKey
            let actor: ClawSnapshotWitness, state: ClawSnapshotWitness, helper: ClawSnapshotWitness
        }
        struct Link: Codable, Equatable { let address: UInt32, value: UInt32 }
        struct Logic: Codable, Equatable {
            let function: UInt32, provider: SnapshotProviderKey, offset: UInt32
            let actor: ClawSnapshotWitness, state: ClawSnapshotWitness
            let allocation: ClawSnapshotWitness, metadata: ClawSnapshotWitness
            let pins: [ClawSnapshotWitness], links: [Link]
        }
        let version: Int
        let providers: Set<SnapshotProviderKey>
        let towers: [Tower], logic: [Logic]
        let fault: Fault?
        let maximumOperations: UInt32
    }
    private func snapshotBindingsBoundary() throws {
        guard snapshotQuiescent, stacklessCallerReserve == nil else { throw ClawSnapshotError.activeFrame }
        // Level 1 has no retained bindings; Level 2's left/right cannons retain
        // TowerBinding and TowerLogicBinding. OrdinaryActivation maps, Skull's
        // resources, PathElevator retirement, conveyor strings and wind audio
        // require other codecs. Empty adapters grant no license to omit them.
        let supported: Set<String> = ["tower", "logic"]
        guard snapshotBindingInventory.allSatisfy({ supported.contains($0.key) || $0.value == 0 }),
              towerBindings.values.allSatisfy({ $0.kind == .left || $0.kind == .right }),
              towerLogicBindings.values.allSatisfy({ $0.rootFunction == TowerKind.left.rawValue || $0.rootFunction == TowerKind.right.rawValue })
        else { throw ClawSnapshotError.incompleteOwners }
    }
    func savedBindingsState() throws -> BindingsSavedState {
        try snapshotBindingsBoundary()
        func witness(_ token: UInt32, _ count: UInt32, _ identity: ClawTokenHeap.AllocationIdentity) -> ClawSnapshotWitness {
            ClawSnapshotWitness(heap: heap, token: token, count: count, identity: identity, interior: true)
        }
        let towers: [BindingsSavedState.Tower] = try towerBindings.keys.sorted().map { token in
            let binding = towerBindings[token]!
            return .init(kind: binding.kind.rawValue, provider: try snapshotProviderKey(binding.provider),
                actor: witness(binding.actor, 0x1b4, binding.actorIdentity), state: witness(binding.state, 0x174, binding.stateIdentity),
                helper: witness(token, 0x7c, binding.helperIdentity))
        }
        let logic: [BindingsSavedState.Logic] = try towerLogicBindings.keys.sorted().map { token in
            let binding = towerLogicBindings[token]!
            return .init(function: binding.rootFunction, provider: try snapshotProviderKey(binding.provider), offset: binding.offset,
                actor: witness(binding.actor, 0x1b4, binding.actorIdentity), state: witness(binding.state, 0x174, binding.stateIdentity),
                allocation: witness(token, 0x174, binding.allocationIdentity), metadata: witness(binding.metadata, 0x14, binding.metadataIdentity),
                pins: binding.environmentPins.map { witness($0.0, $0.1, $0.2) },
                links: binding.environmentLinks.map { .init(address: $0.0, value: $0.1) })
        }
        return .init(version: 1, providers: Set(towers.map(\.provider) + logic.map(\.provider)),
            towers: towers, logic: logic, fault: fault, maximumOperations: native.pointee.maximumOperations)
    }
    func prepareBindingsRestore(_ value: BindingsSavedState, heap plan: ClawTokenHeap.RestorePlan) throws -> () throws -> Void {
        try snapshotBindingsBoundary(); try heap.validateRestore(plan)
        guard value.version == 1, value.towers.count <= 16384, value.logic.count <= 32768,
              value.fault.map({ $0.code != 0 }) ?? true,
              Set(value.towers.map { $0.helper.reference.token }).count == value.towers.count,
              Set(value.logic.map { $0.allocation.reference.token }).count == value.logic.count,
              value.providers == Set(value.towers.map(\.provider) + value.logic.map(\.provider))
        else { throw ClawSnapshotError.invalidState }
        var providers: [SnapshotProviderKey: ObjectAllocationProvider] = [:]
        for key in value.providers {
            guard let provider = snapshotProviders[key]?.value, provider.validObjectAllocationBinding(for: self)
            else { throw ClawSnapshotError.incompleteOwners }
            providers[key] = provider
        }
        func identity(_ witness: ClawSnapshotWitness, count: UInt32) throws -> ClawTokenHeap.AllocationIdentity {
            guard witness.reference.count == count, witness.reference.interior, count > 0,
                  witness.reference.token < UInt32(CLAW_STACK_BASE) || witness.reference.token >= UInt32(CLAW_STACK_END)
            else { throw ClawSnapshotError.invalidState }
            return try witness.resolve(in: plan)
        }
        func kind(_ raw: UInt32, provider: SnapshotProviderKey) throws -> TowerKind {
            guard let kind = TowerKind(rawValue: raw),
                  (kind == .left && provider == .towerCannonLeft) || (kind == .right && provider == .towerCannonRight)
            else { throw ClawSnapshotError.invalidState }
            return kind
        }
        var towers: [UInt32: TowerBinding] = [:], logic: [UInt32: TowerLogicBinding] = [:]
        for record in value.towers {
            towers[record.helper.reference.token] = TowerBinding(kind: try kind(record.kind, provider: record.provider),
                provider: ObjectIdentifier(providers[record.provider]!), actor: record.actor.reference.token, state: record.state.reference.token,
                actorIdentity: try identity(record.actor, count: 0x1b4), stateIdentity: try identity(record.state, count: 0x174),
                helperIdentity: try identity(record.helper, count: 0x7c))
        }
        for record in value.logic {
            _ = try kind(record.function, provider: record.provider)
            guard record.offset == 0x70 || record.offset == 0x78, record.pins.count <= 4096, record.links.count <= 4096
            else { throw ClawSnapshotError.invalidState }
            logic[record.allocation.reference.token] = TowerLogicBinding(rootFunction: record.function,
                provider: ObjectIdentifier(providers[record.provider]!), actor: record.actor.reference.token, state: record.state.reference.token,
                offset: record.offset, metadata: record.metadata.reference.token,
                actorIdentity: try identity(record.actor, count: 0x1b4), stateIdentity: try identity(record.state, count: 0x174),
                allocationIdentity: try identity(record.allocation, count: 0x174), metadataIdentity: try identity(record.metadata, count: 0x14),
                environmentPins: try record.pins.map { ($0.reference.token, $0.reference.count, try identity($0, count: $0.reference.count)) },
                environmentLinks: record.links.map { ($0.address, $0.value) })
        }
        // A SourceGraph is scoped by withSourceGraph; its borrowed CPU/stack
        // views never survive snapshotQuiescent. Object x87 is also scoped by
        // withObjectX87Environment, so there is no between-frame host x87 image.
        // Each witness, including tombstones, comes from this single plan.
        return { [self] in
            try snapshotBindingsBoundary(); try heap.validateInstalledRestore(plan)
            for (key, provider) in providers {
                guard snapshotProviders[key]?.value === provider else { throw ClawSnapshotError.incompleteOwners }
            }
            towerBindings = towers; towerLogicBindings = logic
            native.pointee.maximumOperations = value.maximumOperations
            native.pointee.fault = value.fault?.code ?? 0; native.pointee.faultAddress = value.fault?.address ?? 0
            diagnostic = value.fault?.diagnostic
        }
    }
    var plankTransportActive: Bool { ordinaryEntries.first?.plankKind != nil }
    var lavaMouthTransportActive: Bool { ordinaryEntries.first?.plankKind == .lavaMouth }
    var lavaHandTransportActive: Bool { ordinaryEntries.first?.plankKind == .lavaHand }
    var lavaGeyserTransportActive: Bool { ordinaryEntries.first?.plankKind == .lavaGeyser }
    var aquatisDynamiteTransportActive: Bool { ordinaryEntries.first?.plankKind == .aquatisDynamite }
    func beginPhysicalService(at address: UInt32) -> Bool {
        guard fault == nil, !physicalServiceActive else {
            fail(UInt32(CLAW_FAULT_ABI), at: address, diagnostic: .recursiveCanonicalCall); return false
        }
        guard activeGraph.map(validModule) ?? true else { _ = contextReject(address); return false }
        physicalServiceActive = true; return true
    }
    func endPhysicalService() { physicalServiceActive = false }
    func validatePhysicalReturn(at address: UInt32) -> Bool { validatePhysicalAuthority(at: address) }
    func validatePhysicalAuthority(at address: UInt32) -> Bool {
        guard fault == nil, activeGraph.map(validModule) ?? true,
              activeGraph?.memoryThrowStack.map({ $0==Data(bytes:sourceStack,count:Self.stackSize) }) ?? true,
              activeGraph.map({ graph in graph.tlsPhysicalContainer.map { graph.tlsProvider?.ownsTLSLocal($0, count: 16) == true } ?? true }) ?? true else {
            _ = contextReject(address); return false
        }
        return true
    }

    private func tlsBegin(_ graph: SourceGraph, function: UInt32, pc: UInt32,
                          arguments: [UInt32], context: ClawSourceContext, physical: Bool = false) -> Int? {
        guard let provider = graph.tlsProvider else { return nil }
        var value = TLSObservation(function: function, returnPC: pc, arguments: arguments,
            input: context, stackBefore: Data(bytes: sourceStack, count: Self.stackSize), before: provider.tlsSnapshot())
        value.moduleIndex = moduleBegin(graph, function: function, pc: pc, arguments: arguments, context: context, physical: physical)
        if physical { graph.tlsEvents.append(value); return graph.tlsEvents.count - 1 }
        graph.tlsEntries.append(value); return graph.tlsEntries.count - 1
    }
    private func tlsEnd(_ graph: SourceGraph, _ index: Int?, context: ClawSourceContext,
                        completed: Bool, physical: Bool = false) {
        guard let index, let provider = graph.tlsProvider else { return }
        var value = physical ? graph.tlsEvents[index] : graph.tlsEntries[index]
        value.completed = completed && fault == nil
        value.output = value.completed ? context : graph.tlsOutput ?? context
        value.stackAfter = Data(bytes: sourceStack, count: Self.stackSize); value.after = provider.tlsSnapshot()
        moduleEnd(graph, value.moduleIndex, context: value.output ?? context, completed: value.completed)
        if physical { graph.tlsEvents[index] = value } else { graph.tlsEntries[index] = value }
    }
    private func sourceCPU(_ c: ClawCompilerContext) -> ClawSourceContext {
        .init(size:72,version:1,inputMask:0x7ff,outputMask:0x7ff,eax:c.eax,ebx:c.ebx,ecx:c.ecx,
              edx:c.edx,esi:c.esi,edi:c.edi,ebp:c.ebp,esp:c.esp,eip:c.eip,eflags:c.eflags,
              fsHead:c.fsHead,preserveMask:0x472,reserved0:0,reserved1:0)
    }

    // One copied, single-use request grants only the physical allocation already
    // validated by the active source graph. Providers never receive stack aliases.
    // Implementations are trusted physical owners, not an untrusted plug-in API.
    // The host still checks binding, request lifetime and exact live ownership.
    protocol SourceAllocationProvider: AnyObject {
        var sourceImportTarget: UInt32 { get }
        func validSourceBinding(for host: ClawNativeCanonicalHost) -> Bool
        func allocateSourceLocal(_ request: SourceAllocationRequest) -> UInt32?
        func ownsSourceLocal(_ token: UInt32, count: UInt32) -> Bool
        func sourceLocalSnapshot(_ token: UInt32) -> Data?
    }
    struct SourceAllocationRequest {
        let slot: UInt32, target: UInt32, returnPC: UInt32
        let arguments: [UInt32]
        let context: ClawSourceContext
        let frame: Data, stack: Data
        private final class Lease {
            weak var owner: ClawNativeCanonicalHost?
            weak var graph: SourceGraph?
            weak var provider: SourceAllocationProvider?
            let thread = pthread_self()
            var consumed = false
            var active = true
            init(owner: ClawNativeCanonicalHost, graph: SourceGraph, provider: SourceAllocationProvider?) {
                self.owner = owner; self.graph = graph; self.provider = provider
            }
        }
        private let lease: Lease
        fileprivate init(host: ClawNativeCanonicalHost, graph: SourceGraph,
                         target: UInt32, provider: SourceAllocationProvider?, event: SourceLocalAllocator.Event) {
            slot = event.function; self.target = target; returnPC = event.returnPC
            arguments = event.arguments; context = event.context
            frame = event.frame; stack = event.stack
            lease = Lease(owner: host, graph: graph, provider: provider)
        }
        func consume(for host: ClawNativeCanonicalHost, provider: SourceAllocationProvider? = nil) -> Bool {
            guard pthread_equal(lease.thread, pthread_self()) != 0,
                  lease.active, !lease.consumed, lease.owner === host, lease.provider === provider,
                  let graph = lease.graph, host.activeGraph === graph,
                  host.fault == nil, host.validModule(graph), !host.contextEntries.isEmpty else { return false }
            lease.consumed = true
            return true
        }
        fileprivate func validReturn(for host: ClawNativeCanonicalHost) -> Bool {
            guard pthread_equal(lease.thread, pthread_self()) != 0, let graph = lease.graph else { return false }
            return lease.active && lease.consumed && lease.owner === host &&
                host.activeGraph === graph && host.fault == nil && host.validModule(graph)
        }
        fileprivate func invalidate() { lease.active = false }
    }

    // Explicit physical LocalAlloc policy: preserve every input register/flag
    // except EAX and the stdcall ESP/EIP return. This is a supported physical
    // convention, not a claim that every Windows allocator preserves volatiles.
    // The service owns actual same-heap allocations until it is released.
    // Its IAT binding is one exact four-byte heap allocation, owned or borrowed;
    // borrowing an interior slot of a larger image block is outside this unit API.
    final class SourceLocalAllocator {
        struct Event {
            let function: UInt32, returnPC: UInt32
            let arguments: [UInt32]
            let context: ClawSourceContext
            let frame: Data, stack: Data
        }
        private weak var owner: ClawNativeCanonicalHost?
        private let heap: ClawTokenHeap
        private let thread = pthread_self()
        fileprivate let importTarget: UInt32
        private let importStorage: UnsafeMutablePointer<UInt8>?
        private let importIdentity: ClawTokenHeap.AllocationIdentity?
        fileprivate let provider: SourceAllocationProvider?
        private let ownsImport: Bool
        private var nextToken: UInt32
        private var allocations: [UInt32: (pointer: UnsafeMutablePointer<UInt8>, count: UInt32, identity: ClawTokenHeap.AllocationIdentity)] = [:]
        private(set) var events: [Event] = []
        // Standalone unit failure policy; shared providers own their own policy.
        var failAllocation = false

        init?(host: ClawNativeCanonicalHost, importTarget: UInt32, allocationBase: UInt32 = 0x62000000) {
            guard host.activeGraph == nil, host.frames.isEmpty, host.fault == nil,
                  importTarget >= 0x710000, importTarget < 0x711000,
                  claw_canonical_lookup(importTarget) == nil,
                  allocationBase >= 0x03000000, allocationBase < 0x70000000,
                  allocationBase & 7 == 0 else { return nil }
            self.owner = host; self.heap = host.heap; self.provider = nil
            self.importTarget = importTarget; self.nextToken = allocationBase
            if host.heap.overlaps(0x546aa8, count: 4) {
                guard let identity = host.heap.allocationIdentity(at: 0x546aa8, count: 4),
                      let p = host.heap.lookupBytes(0x546aa8, count: 4),
                      UnsafeRawPointer(p).loadUnaligned(as: UInt32.self).littleEndian == importTarget else { return nil }
                importStorage = p; importIdentity = identity; ownsImport = false
            } else {
                importStorage = host.heap.storeBytes(token: 0x546aa8, count: 4); ownsImport = true
                importIdentity = host.heap.allocationIdentity(at: 0x546aa8, count: 4)!
                var value = importTarget.littleEndian
                withUnsafeBytes(of: &value) { UnsafeMutableRawPointer(importStorage!).copyMemory(from: $0.baseAddress!, byteCount: 4) }
            }
        }
        init?(host: ClawNativeCanonicalHost, provider: SourceAllocationProvider) {
            guard host.activeGraph == nil, host.frames.isEmpty, host.fault == nil,
                  provider.sourceImportTarget >= 0x710000,
                  provider.sourceImportTarget < 0x711000,
                  claw_canonical_lookup(provider.sourceImportTarget) == nil,
                  provider.validSourceBinding(for: host) else { return nil }
            self.owner = host; self.heap = host.heap; self.provider = provider
            self.importTarget = provider.sourceImportTarget
            self.nextToken = 0; self.importStorage = nil; self.importIdentity = nil
            self.ownsImport = false
        }
        fileprivate func valid(for host: ClawNativeCanonicalHost) -> Bool {
            guard owner === host, pthread_equal(thread, pthread_self()) != 0 else { return false }
            if let provider {
                return provider.sourceImportTarget == importTarget && provider.validSourceBinding(for: host)
            }
            guard let importStorage, let importIdentity else { return false }
            return heap.allocationIdentity(at: 0x546aa8, count: 4) === importIdentity &&
                heap.lookupBytes(0x546aa8, count: 4) == importStorage &&
                UnsafeRawPointer(importStorage).loadUnaligned(as: UInt32.self).littleEndian == importTarget
        }
        fileprivate func allocate(_ count: UInt32, host: ClawNativeCanonicalHost,
                                  request: SourceAllocationRequest) -> UInt32? {
            defer { request.invalidate() }
            guard valid(for: host), ClawNativeCanonicalHost.supportsSourceFactorySize(count) else { return nil }
            if let provider {
                let result = provider.allocateSourceLocal(request)
                guard request.validReturn(for: host),
                      valid(for: host), let result,
                      result == 0 || provider.ownsSourceLocal(result, count: count) else { return nil }
                return result
            }
            guard request.consume(for: host) else { return nil }
            if failAllocation { return 0 }
            let extent = (count + 3) & ~3
            let end = UInt64(nextToken) + UInt64(extent)
            guard end < 0x70000000, !heap.overlaps(nextToken, count: extent) else { return nil }
            let token = nextToken
            let bytes = heap.storeBytes(token: token, count: count)
            bytes.update(repeating: 0, count: Int(count))
            allocations[token] = (bytes, count, heap.allocationIdentity(at: token, count: count)!)
            nextToken = UInt32((end + 7) & ~7)
            return token
        }
        fileprivate func owns(_ token: UInt32, count: UInt32) -> Bool {
            guard pthread_equal(thread, pthread_self()) != 0 else { return false }
            if let provider {
                guard let owner, valid(for: owner) else { return false }
                return provider.ownsSourceLocal(token, count: count)
            }
            guard let allocation = allocations[token], allocation.count == count else { return false }
            return heap.allocationIdentity(at: token, count: count) === allocation.identity &&
                heap.lookupBytes(token, count: count) == allocation.pointer
        }
        func allocationSnapshot(_ token: UInt32) -> Data? {
            guard pthread_equal(thread, pthread_self()) != 0 else { return nil }
            if let provider {
                guard let owner, valid(for: owner) else { return nil }
                return provider.sourceLocalSnapshot(token)
            }
            guard let allocation = allocations[token], owns(token, count: allocation.count) else { return nil }
            return Data(bytes: allocation.pointer, count: Int(allocation.count))
        }
        fileprivate func observe(_ event: Event) { events.append(event) }
        deinit {
            for (token, span) in allocations where heap.allocationIdentity(at: token, count: span.count) === span.identity { heap.free(token) }
            if ownsImport, let importIdentity,
               heap.allocationIdentity(at: 0x546aa8, count: 4) === importIdentity { heap.free(0x546aa8) }
        }
    }

    // Explicit physical GetCursorPos unit policy. The caller owns the record's
    // actual heap allocation, including any surrounding bytes. TRUE writes a
    // signed POINT; FALSE writes nothing. EAX is BOOL and every other CPU field
    // is preserved except the stdcall ESP/EIP return. No source routine or
    // record allocation is replaced by this service.
    final class SourceCursorService {
        struct Event {
            let function: UInt32, returnPC: UInt32
            let arguments: [UInt32]
            let context: ClawSourceContext
            let returnedContext: ClawSourceContext
            let frame: Data, stack: Data, allocation: Data
        }
        private weak var owner: ClawNativeCanonicalHost?
        private let heap: ClawTokenHeap
        private let thread = pthread_self()
        fileprivate let recordToken: UInt32
        private let allocationBase: UInt32, allocationCount: UInt32
        private let recordIdentity: ClawTokenHeap.AllocationIdentity
        private let importIdentity: ClawTokenHeap.AllocationIdentity
        private let importTarget: UInt32
        private let ownsImport: Bool
        private let success: Bool
        private let x: Int32, y: Int32
        private(set) var events: [Event] = []

        init?(host: ClawNativeCanonicalHost, recordToken: UInt32,
              allocationBase: UInt32, allocationCount: UInt32,
              importTarget: UInt32, success: Bool, x: Int32, y: Int32) {
            guard host.activeGraph == nil, host.frames.isEmpty, host.fault == nil,
                  importTarget >= 0x710000, importTarget < 0x711000,
                  claw_canonical_lookup(importTarget) == nil,
                  recordToken >= 0x03000000, UInt64(recordToken) + 0x68 < 0x70000000,
                  recordToken >= allocationBase,
                  UInt64(recordToken) + 0x68 <= UInt64(allocationBase) + UInt64(allocationCount),
                  let identity = host.heap.allocationIdentity(at: allocationBase, count: allocationCount),
                  host.heap.lookupBytes(recordToken, count: 0x68) != nil else { return nil }
            self.owner = host; self.heap = host.heap; self.recordToken = recordToken
            self.allocationBase = allocationBase; self.allocationCount = allocationCount
            self.recordIdentity = identity; self.importTarget = importTarget
            self.success = success; self.x = x; self.y = y
            if host.heap.overlaps(0x546cd0, count: 4) {
                guard let identity = host.heap.allocationIdentity(at: 0x546cd0, count: 4),
                      let p = host.heap.lookupBytes(0x546cd0, count: 4),
                      UnsafeRawPointer(p).loadUnaligned(as: UInt32.self).littleEndian == importTarget else { return nil }
                importIdentity = identity; ownsImport = false
            } else {
                let p = host.heap.storeBytes(token: 0x546cd0, count: 4)
                importIdentity = host.heap.allocationIdentity(at: 0x546cd0, count: 4)!
                ownsImport = true
                var value = importTarget.littleEndian
                withUnsafeBytes(of: &value) { UnsafeMutableRawPointer(p).copyMemory(from: $0.baseAddress!, byteCount: 4) }
            }
        }
        fileprivate func valid(for host: ClawNativeCanonicalHost) -> Bool {
            guard owner === host, pthread_equal(thread, pthread_self()) != 0,
                  heap.allocationIdentity(at: allocationBase, count: allocationCount) === recordIdentity,
                  heap.allocationIdentity(at: 0x546cd0, count: 4) === importIdentity,
                  let p = heap.lookupBytes(0x546cd0, count: 4) else { return false }
            return UnsafeRawPointer(p).loadUnaligned(as: UInt32.self).littleEndian == importTarget
        }
        func allocationSnapshot() -> Data? {
            guard let owner, valid(for: owner),
                  let p = heap.lookupBytes(allocationBase, count: allocationCount) else { return nil }
            return Data(bytes: p, count: Int(allocationCount))
        }
        fileprivate func perform(host: ClawNativeCanonicalHost) -> UInt32? {
            guard valid(for: host), let p = heap.lookupBytes(recordToken + 0x5c, count: 8) else { return nil }
            if success {
                var point = [UInt32(bitPattern: x).littleEndian, UInt32(bitPattern: y).littleEndian]
                point.withUnsafeMutableBytes { UnsafeMutableRawPointer(p).copyMemory(from: $0.baseAddress!, byteCount: 8) }
            }
            return success ? 1 : 0
        }
        fileprivate func observe(_ event: Event) { events.append(event) }
        deinit {
            if ownsImport && heap.allocationIdentity(at: 0x546cd0, count: 4) === importIdentity { heap.free(0x546cd0) }
        }
    }

    // No borrowed context pointers are exposed or retained by this capability.
    // It is deliberately non-Sendable. A retained capability expires on return;
    // copied CPU/stack snapshots remain plain data with no memory authority.
    final class SourceGraph {
        fileprivate var threadHeadBinding: (address: UInt32, identity: ClawTokenHeap.AllocationIdentity, value: UInt32)?
        fileprivate var staticTableExpected: [UInt32]?
        fileprivate var staticTableIdentity: ClawTokenHeap.AllocationIdentity?
        fileprivate var staticRangeIdentity: ClawTokenHeap.AllocationIdentity?
        fileprivate var rangeReceiverSpans: [UInt32: ClawTokenHeap.AllocationIdentity] = [:]
        fileprivate var rangeGlobalSpans: [UInt32: (count: UInt32, identity: ClawTokenHeap.AllocationIdentity)] = [:]
        fileprivate var rangeAllocations: [UInt32: CrtAllocationWitness] = [:]
        fileprivate var listOwnedFrame: UInt32?
        fileprivate var listOwnedFunction: UInt32?
        fileprivate var listOwnedReceiver: UInt32 = 0
        fileprivate var listChildReceiver: UInt32 = 0
        fileprivate var listModulePrefix: [UInt32]?
        fileprivate var finalStaticRecords=false
        fileprivate var finalOwnedFrame: UInt32?
        fileprivate var finalOwnedFunction: UInt32?
        fileprivate var finalOwnedEntry: ClawSourceContext?
        fileprivate var staticListRecords=false
        fileprivate var extendedStaticRecords=false
        fileprivate var staticArrayEntry: ClawSourceContext?
        fileprivate var staticArrayElements: UInt32 = 0
        fileprivate var staticArrayElementReceiver: UInt32?
        fileprivate var staticFactoryFrame: UInt32?
        fileprivate var activeRangeIndex: Int?
        fileprivate var activeRangeFSHead: UInt32?
        fileprivate var stringFrontierSpans: [UInt32: (count: UInt32, identity: ClawTokenHeap.AllocationIdentity)] = [:]
        fileprivate var staticReadonlyBytes: [UInt32:Data] = [:]
        fileprivate var memoryThrowFrame: UInt32?
        fileprivate var memoryThrowEntry: ClawSourceContext?
        fileprivate var memoryThrowAncestry: [UInt32] = []
        fileprivate var memoryThrowStack: Data?
        fileprivate var memoryThrowSpans: [UInt32:(UInt32,ClawTokenHeap.AllocationIdentity)] = [:]
        fileprivate var memoryThrowReadonly: [UInt32:Data] = [:]
        fileprivate var staticApplicationFrame: UInt32?
        fileprivate var activeStaticStringIndex: Int?
        fileprivate var staticStringFrame: UInt32?
        fileprivate var stringGetterReturned=false
        fileprivate var stringLengthReturned=false
        fileprivate var staticLockIdentity: ClawTokenHeap.AllocationIdentity?
        fileprivate var staticWrapper: UInt32?
        fileprivate var staticFrame: UInt32?
        fileprivate var staticDriverFrame: UInt32?
        fileprivate var staticDriverEnd: UInt32?
        fileprivate var staticConstructorReturn: ClawSourceContext?
        private var sourceFaultPrefix: ClawSourceContext?
        // The first failed child supplies the actual deepest CPU. Parent
        // source contexts may still be at their unadopted child entry. Only a
        // new explicit root may clear this receipt; no failed ancestor replaces it.
        fileprivate var staticFaultPrefix: ClawSourceContext? {
            get { sourceFaultPrefix }
            set {
                if newValue==nil { sourceFaultPrefix=nil }
                else if sourceFaultPrefix==nil { sourceFaultPrefix=newValue }
            }
        }
        var staticObserver: ((StaticObservation) -> Void)?
        // Prepared real dispatcher-child entries. The source table walker
        // remains a separate recovery/acceptance requirement.
        func invokeStaticWrapper(_ function: UInt32, context: inout ClawSourceContext) -> Completion {
            guard let owner else { return Completion(completed: false, eax: nil, fault: nil) }
            return owner.invokeStaticWrapper(self, function: function, context: &context)
        }
        func invokeStaticTablePrefix(context: inout ClawSourceContext) -> Completion {
            guard let owner else { return Completion(completed:false,eax:nil,fault:nil) }
            return owner.invokeStaticTablePrefix(self,context:&context)
        }
        fileprivate var crtProvider: SourceCrtProvider?
        var crtObserver: ((CrtObservation) -> Void)?
        fileprivate(set) var crtOutput: ClawSourceContext?
        fileprivate(set) var crtStack: Data?
        fileprivate var crtLeafReturn: (function: UInt32, frame: UInt32, context: ClawSourceContext)?
        func invokeCrtSource(at root: CrtRoot, context: inout ClawSourceContext) -> Completion {
            guard let owner else { return Completion(completed: false, eax: nil, fault: nil) }
            return owner.invokeCrtSource(self, root: root, context: &context)
        }
        func invokeCrtRegistrationLeaf(_ function: UInt32, context: inout ClawSourceContext) -> Completion {
            guard let owner else { return Completion(completed:false,eax:nil,fault:nil) }
            return owner.invokeCrtRegistrationLeaf(self,function:function,context:&context)
        }
        fileprivate weak var owner: ClawNativeCanonicalHost?
        fileprivate let thread = pthread_self()
        fileprivate var localAllocator: SourceLocalAllocator?
        fileprivate var cursorService: SourceCursorService?
        fileprivate var managerProvider: SourceManagerProvider?
        fileprivate var locksProvider: SourceLocksProvider?
        fileprivate(set) var locksEvents: [LocksObservation] = []
        fileprivate(set) var locksEntries: [LocksObservation] = []
        fileprivate(set) var locksOutput: ClawSourceContext?
        fileprivate(set) var locksStack: Data?
        fileprivate(set) var moduleObservations: [ModuleObservation] = []
        fileprivate var moduleOrder = 0
        fileprivate var returnedModule: UInt32?
        fileprivate var applicationModule: UInt32?
        fileprivate var tlsGetterReturn: UInt32 = 0x50229e
        fileprivate var moduleProvider: SourceModuleProvider?
        fileprivate var moduleAllocations: [UInt32: (count: UInt32, identity: ClawTokenHeap.AllocationIdentity, capacity: UInt32, generation: UInt64?)] = [:]
        fileprivate var tlsProvider: SourceTLSProvider?
        fileprivate var tlsOwner: UInt32 = 0
        fileprivate var applicationProvider: SourceApplicationProvider?
        fileprivate var applicationReceiver: UInt32 = 0
        fileprivate var applicationSpans: [UInt32: (count: UInt32, identity: ClawTokenHeap.AllocationIdentity)] = [:]
        fileprivate var tlsPhysicalContainer: UInt32?
        fileprivate var tlsOwnedFactory: (token: UInt32, count: UInt32)?
        fileprivate(set) var tlsEntries: [TLSObservation] = []
        fileprivate(set) var tlsEvents: [TLSObservation] = []
        fileprivate(set) var tlsOutput: ClawSourceContext?
        fileprivate(set) var tlsStack: Data?
        fileprivate var managerIdentity: ClawTokenHeap.AllocationIdentity?
        fileprivate var manager: UInt32 = 0
        fileprivate(set) var managerEvents: [SourceManagerEvent] = []
        fileprivate(set) var managerEntries: [SourceManagerEntry] = []
        fileprivate(set) var managerOutput: ClawSourceContext?
        fileprivate(set) var managerStack: Data?
        fileprivate init(owner: ClawNativeCanonicalHost, localAllocator: SourceLocalAllocator?, cursorService: SourceCursorService?, managerProvider: SourceManagerProvider?) {
            self.managerProvider = managerProvider
            self.owner = owner; self.localAllocator = localAllocator; self.cursorService = cursorService
        }
        func invokeCompiler(at site: CompilerSite, context: inout ClawCompilerContext) -> Completion {
            guard let owner else { return Completion(completed: false, eax: nil, fault: nil) }
            return owner.invokeCompiler(self, site: site, context: &context, nested: false)
        }
        func invokeSource(at site: SourceSite, context: inout ClawSourceContext) -> Completion {
            guard let owner else { return Completion(completed: false, eax: nil, fault: nil) }
            return owner.invokeSource(self, site: site, context: &context)
        }
        func registerApplicationTLSOwner(module: UInt32) -> Bool {
            guard let owner, owner.validateGraph(self, at: module), owner.contextEntries.isEmpty,
                  returnedModule == module, let provider = moduleProvider,
                  owner.retainModuleAllocation(self, token: module, count: 0x1074),
                  provider.registerApplicationTLSOwner(module), provider.ownsApplicationTLSOwner(module) else { return false }
            applicationModule = module; return true
        }
        @discardableResult func writeStack(at token: UInt32, data: Data) -> Bool {
            if let owner, owner.crtObservationActive {
                _ = owner.contextReject(token,.recursiveCanonicalCall); return false
            }
            guard let owner, owner.validateGraph(self, at: token), owner.contextEntries.isEmpty else { return false }
            guard data.count <= Int(UInt32.max), token >= CLAW_STACK_BASE,
                  UInt64(token) + UInt64(data.count) <= CLAW_STACK_END else {
                owner.fail(UInt32(CLAW_FAULT_MEMORY), at: token, diagnostic: .invalidMemorySpan)
                return false
            }
            guard let target = owner.resolveBytes(token, count: UInt32(data.count)) else { return false }
            data.withUnsafeBytes { if let p = $0.baseAddress { UnsafeMutableRawPointer(target).copyMemory(from: p, byteCount: data.count) } }
            return true
        }
        func stackSnapshot() -> Data? {
            guard let owner, owner.validateGraph(self, at: UInt32(CLAW_STACK_BASE)), owner.contextEntries.isEmpty else { return nil }
            return Data(bytes: owner.sourceStack, count: ClawNativeCanonicalHost.stackSize)
        }
    }
    private var activeGraph: SourceGraph?
    private var sourceThread: pthread_t?
    private var contextEntries: [UInt32] = []

    private func validateGraph(_ graph: SourceGraph, at address: UInt32) -> Bool {
        guard fault == nil else { return false }
        guard validModule(graph) else { _ = contextReject(address); return false }
        guard activeGraph === graph, pthread_equal(graph.thread, pthread_self()) != 0 else {
            fail(UInt32(CLAW_FAULT_ABI), at: address, diagnostic: .unsupportedABI)
            return false
        }
        return true
    }
    private func matchingThreadHead(_ graph: SourceGraph, fsHead: UInt32) -> Bool {
        graph.threadHeadBinding.map { $0.value==fsHead } ?? true
    }
    private func materializeThreadHead(_ graph: SourceGraph, fsHead: UInt32, at address: UInt32,
                                       executedFaultPrefix: Bool = false) -> Bool {
        // A native execution fault does not revoke intact guest backing. Publish
        // only the executed FS value, without clearing that fault or bypassing
        // allocation, image, provider, thread or graph authority.
        func authority() -> Bool {
            activeGraph === graph && pthread_equal(graph.thread,pthread_self()) != 0 && validModule(graph)
        }
        guard executedFaultPrefix ? authority() : validateGraph(graph,at:address),
              !crtObservationActive,!physicalServiceActive else { return false }
        guard var head=graph.threadHeadBinding else { return true }
        guard let word=heap.lookup(head.address,words:1) else { _=contextReject(address);return false }
        word[0]=fsHead;head.value=fsHead;graph.threadHeadBinding=head
        return executedFaultPrefix ? authority() : validateGraph(graph,at:address)
    }
    func withSourceGraph<T>(localAllocator: SourceLocalAllocator? = nil, cursorService: SourceCursorService? = nil, managerProvider: SourceManagerProvider? = nil, body: (SourceGraph) -> T) -> T? {
        guard fault == nil else { return nil }
        guard activeGraph == nil, frames.isEmpty else {
            fail(UInt32(CLAW_FAULT_ABI), at: 0, diagnostic: .recursiveCanonicalCall)
            return nil
        }
        guard !heap.overlaps(UInt32(CLAW_STACK_BASE), count: UInt32(Self.stackSize)) else {
            fail(UInt32(CLAW_FAULT_MEMORY), at: UInt32(CLAW_STACK_BASE), diagnostic: .invalidMemorySpan)
            return nil
        }
        if let sourceThread, pthread_equal(sourceThread, pthread_self()) == 0 {
            fail(UInt32(CLAW_FAULT_ABI), at: 0, diagnostic: .unsupportedABI)
            return nil
        }
        sourceThread = pthread_self()
        if let localAllocator, !localAllocator.valid(for: self) {
            _ = contextReject(0x546aa8); return nil
        }
        if let cursorService, !cursorService.valid(for: self) {
            _ = contextReject(0x546cd0); return nil
        }
        if let managerProvider, !managerProvider.validManagerBinding(for: self) {
            _ = contextReject(0x502fb6); return nil
        }
        let graph = SourceGraph(owner: self, localAllocator: localAllocator, cursorService: cursorService, managerProvider: managerProvider)
        activeGraph = graph
        sourceStack.update(repeating: 0, count: Self.stackSize)
        remainingOperations.pointee = native.pointee.maximumOperations == 0 ? 200_000_000 : UInt64(native.pointee.maximumOperations)
        let previousBudget = native.pointee.remainingOperations
        native.pointee.remainingOperations = remainingOperations
        defer {
            activeGraph = nil
            graph.localAllocator = nil
            graph.cursorService = nil
            graph.managerProvider = nil
            graph.managerIdentity = nil
            native.pointee.compilerContext = nil
            native.pointee.sourceContext = nil
            native.pointee.sourceReturnPC = 0
            native.pointee.remainingOperations = previousBudget
        }
        return heap.withStableFreedStorage { body(graph) }
    }
    private func contextResult(_ completed: Bool = false, eax: UInt32? = nil) -> Completion {
        Completion(completed: completed && fault == nil, eax: fault == nil && completed ? eax : nil, fault: fault)
    }
    private func contextReject(_ address: UInt32, _ reason: Diagnostic = .unsupportedABI) -> Completion {
        fail(UInt32(CLAW_FAULT_ABI), at: address, diagnostic: reason)
        return contextResult()
    }
    private func validCPU(esp: UInt32, flags: UInt32, fs: UInt32) -> Bool {
        esp & 3 == 0 && esp >= CLAW_STACK_BASE && UInt64(esp) + 4 <= CLAW_STACK_END &&
        flags & ~0x8d7 == 0 && flags & 2 != 0 &&
        (fs == UInt32.max || (fs & 3 == 0 && fs >= CLAW_STACK_BASE && UInt64(fs) + 12 <= CLAW_STACK_END))
    }
    private func stackWord(_ token: UInt32) -> UInt32 {
        var word: UInt32 = 0
        withUnsafeMutableBytes(of: &word) { target in
            target.copyMemory(from: UnsafeRawBufferPointer(start: sourceStack.advanced(by: Int(token - UInt32(CLAW_STACK_BASE))), count: 4))
        }
