              (!nested || (native.pointee.sourceReturnPC == 0x502ea8 && stackWord(frame) == 0x502ea8)),
              call.function == (cached ? target : edge.target),
              context.size == 72, context.version == 1, context.reserved0 == 0, context.reserved1 == 0,
              context.inputMask == 0x7ff, context.outputMask == 0x7ff, context.preserveMask == 0,
              context.eip == call.function, context.esp == call.stackPointer,
              UInt64(context.esp) + UInt64(edge.delta) == UInt64(frame),
              context.esp == parent.esp, context.eip == parent.eip,
              context.eax == parent.eax, context.ebx == parent.ebx, context.ecx == parent.ecx,
              context.edx == parent.edx, context.esi == parent.esi, context.edi == parent.edi,
              context.ebp == parent.ebp, context.eflags == parent.eflags, context.fsHead == parent.fsHead,
              validCPU(esp: context.esp, flags: context.eflags, fs: context.fsHead),
              UInt64(context.esp) + 4 * (1 + UInt64(edge.count)) <= UInt64(CLAW_STACK_END),
              stackWord(context.esp) == call.sourceReturnPC,
              args.enumerated().allSatisfy({ stackWord(context.esp + 4 + UInt32($0.offset)*4) == $0.element }),
              !cached || context.ebx == target else { _ = contextReject(call.function); return nil }
        let expected: [UInt32]
        switch edge.continuation {
        case 0x502e60: expected = []
        case 0x502e8e, 0x502ed2: expected = [0x540a90]
        case 0x502ef1: expected = [context.ebp]
        case 0x502ee8, 0x502efe: expected = [0x5408f0 &+ context.edi &* 24]
        default: expected = [context.eax]
        }
        guard args == expected else { _ = contextReject(call.function); return nil }
        var observed = context; observed.eip = target
        let before = provider.locksSnapshot(), stackBefore = Data(bytes: sourceStack, count: Self.stackSize)
        let moduleTrace = moduleBegin(graph, function: edge.target, pc: call.sourceReturnPC, arguments: args, context: observed, physical: true)
        let request = SourceLocksRequest(host: self, graph: graph, provider: provider, slot: edge.target,
            target: target, returnPC: call.sourceReturnPC, arguments: args, context: observed, stack: stackBefore)
        defer { request.invalidate() }
        let value:UInt32?,accepted:Bool
        if graph.finalStaticRecords,edge.target==0x546abc,let crt=graph.crtProvider as? SourceFinalPlatformProvider,crt.finalPlatformReady {
            guard crt.crtImportTarget(edge.target)==target else { _=contextReject(call.function);return nil }
            let physical=SourceCrtRequest(self,graph,crt,function:edge.target,target:target,returnPC:call.sourceReturnPC,arguments:args,context:observed,stack:stackBefore)
            defer { physical.invalidate() }
            value=crt.serviceSourceCrt(physical);accepted=value != nil && physical.validReturn(for:self)
        } else {
            value=provider.serviceSourceLocks(request);accepted=value != nil && request.validReturn(for:self)
        }
        if !accepted && fault == nil { _ = contextReject(call.function) }
        var output = observed
        if accepted { output.eax = value!; output.esp += 4 + edge.count*4; output.eip = call.sourceReturnPC }
        moduleEnd(graph, moduleTrace, context: output, completed: accepted)
        graph.locksEvents.append(.init(function: edge.target, target: call.function, importedTarget: target,
            returnPC: call.sourceReturnPC, arguments: args, input: observed, stackBefore: stackBefore, before: before,
            output: output, stackAfter: Data(bytes: sourceStack, count: Self.stackSize), after: provider.locksSnapshot(),
            result: accepted ? value : nil, completed: accepted))
        guard accepted else { graph.locksOutput = observed; graph.tlsOutput = observed; return nil }
        context.eax = output.eax; context.esp = output.esp; context.eip = output.eip
        pointer.pointee = context; return value
    }

    // Check only stable table publication boundaries. A moving realloc retires
    // the old table before the admitted body publishes its new pointer.
    private func validManagerTable(_ graph: SourceGraph) -> Bool {
        guard let provider = graph.managerProvider, provider.ownsSourceManager(graph.manager),
              let storage = heap.lookup(graph.manager, words: 13) else { return false }
        let count = UInt64(storage[1]) * 8
        if storage[4] == 0 { return count == 0 }
        return count <= UInt32.max && provider.ownsSourceBlock(storage[4], count: UInt32(count))
    }
    private func validManager(_ graph: SourceGraph) -> Bool {
        guard fault == nil, activeGraph === graph, validModule(graph),
              pthread_equal(graph.thread, pthread_self()) != 0,
              let provider = graph.managerProvider,
              provider.validManagerBinding(for: self), provider.ownsSourceManager(graph.manager),
              graph.tlsProvider.map({ $0.validTLSBinding(for: self) }) ?? true,
              graph.tlsOwnedFactory.map({ graph.tlsProvider?.ownsTLSLocal($0.token, count: $0.count) == true }) ?? true,
              let identity = graph.managerIdentity else { return false }
        return heap.containingAllocationIdentity(at: graph.manager, count: 0x34) === identity
    }
    private enum ManagerOperation {
        case tls, initialize, enter, allocate, handle, unlock, reallocate
        case failedHandle, failedLock, failedLeave, lock, leave, fill, missingThrow
    }
    private struct ManagerEdge {
        let root: UInt32, callPC: UInt32, continuation: UInt32, target: UInt32, delta: UInt32
        let operation: ManagerOperation
        var preserve: UInt32 { operation == .fill ? 0x452 : 0x472 }
        var count: UInt32 {
            switch operation {
            case .tls, .missingThrow: return 0
            case .allocate: return 2
            case .reallocate, .fill: return 3
            default: return 1
            }
        }
    }
    // Reviewed original CALL metadata, distinct from the dynamic continuation
    // and actual CPU/frame/heap witnesses checked below. Cached calls use the
    // imported target held in EBX; all other import calls name their exact slot.
    private static let managerEdges: [ManagerEdge] = [
        .init(root: 0x502fb6, callPC: 0x502fd8, continuation: 0x502fde, target: 0x546a90, delta: 8, operation: .tls),
        .init(root: 0x502fb6, callPC: 0x502fe5, continuation: 0x502fea, target: 0x4f50fd, delta: 8, operation: .missingThrow),
        .init(root: 0x502fb6, callPC: 0x502fee, continuation: 0x502ff4, target: 0x546aa4, delta: 12, operation: .initialize),
        .init(root: 0x502ff8, callPC: 0x503008, continuation: 0x50300e, target: 0x546aac, delta: 32, operation: .enter),
        .init(root: 0x502ff8, callPC: 0x50305c, continuation: 0x503062, target: 0x546b1c, delta: 36, operation: .allocate),
        .init(root: 0x502ff8, callPC: 0x503065, continuation: 0x50306b, target: 0x546a8c, delta: 32, operation: .handle),
        .init(root: 0x502ff8, callPC: 0x50306e, continuation: 0x503074, target: 0x5469c8, delta: 32, operation: .unlock),
        .init(root: 0x502ff8, callPC: 0x503080, continuation: 0x503086, target: 0x546a88, delta: 40, operation: .reallocate),
        .init(root: 0x502ff8, callPC: 0x503097, continuation: 0x50309d, target: 0x546a8c, delta: 32, operation: .failedHandle),
        .init(root: 0x502ff8, callPC: 0x50309e, continuation: 0x5030a0, target: 0x5469c4, delta: 32, operation: .failedLock),
        .init(root: 0x502ff8, callPC: 0x5030a4, continuation: 0x5030aa, target: 0x546a9c, delta: 32, operation: .failedLeave),
        .init(root: 0x502ff8, callPC: 0x5030aa, continuation: 0x5030af, target: 0x4f50fd, delta: 28, operation: .missingThrow),
        .init(root: 0x502ff8, callPC: 0x5030b3, continuation: 0x5030b5, target: 0x5469c4, delta: 32, operation: .lock),
        .init(root: 0x502ff8, callPC: 0x5030ce, continuation: 0x5030d3, target: 0x4a4a20, delta: 40, operation: .fill),
        .init(root: 0x502ff8, callPC: 0x5030fb, continuation: 0x503101, target: 0x546a9c, delta: 32, operation: .leave),
    ]
    private func callManagerDependency(_ call: ClawCall, graph: SourceGraph) -> UInt32? {
        guard validManager(graph), let provider = graph.managerProvider,
              !contextEntries.isEmpty, !frames.isEmpty,
              graph.tlsProvider != nil || (contextEntries.count == 1 && frames.count == 1),
              let edge = Self.managerEdges.first(where: { $0.root == contextEntries.last && $0.continuation == call.sourceReturnPC }),
              let parentPointer = native.pointee.sourceContext, native.pointee.compilerContext == nil,
              let pointer = call.sourceContext, pointer != parentPointer, call.compilerContext == nil,
              call.argumentCount == edge.count, call.receiver == 0, call.receiver2 == 0, call.x87ArgumentCount == 0 else {
            _ = contextReject(call.function); return nil
        }
        let cached = edge.operation == .lock || edge.operation == .failedLock
        let target = provider.managerImportTarget(edge.target) ?? edge.target
        guard call.function == (cached ? target : edge.target) else { _ = contextReject(call.function); return nil }
        var context = pointer.pointee
        let parent = parentPointer.pointee, frame = frames.last!, manager = graph.manager
        let args = withUnsafeBytes(of: call.arguments) { Array($0.bindMemory(to: UInt32.self).prefix(Int(edge.count))) }
        guard context.size == 72, context.version == 1, context.reserved0 == 0, context.reserved1 == 0,
              context.inputMask == 0x7ff, context.outputMask == 0x7ff, context.preserveMask == edge.preserve,
              context.eip == call.function, call.stackPointer == context.esp,
              UInt64(context.esp) + UInt64(edge.delta) == UInt64(frame),
              UInt64(context.esp) + 4 == UInt64(parent.esp),
              validCPU(esp: context.esp, flags: context.eflags, fs: context.fsHead),
              context.eax == parent.eax, context.ebx == parent.ebx, context.ecx == parent.ecx,
              context.edx == parent.edx, context.esi == parent.esi, context.edi == parent.edi,
              context.ebp == parent.ebp, context.eflags == parent.eflags, context.fsHead == parent.fsHead,
              context.esi == manager,
              args.enumerated().allSatisfy({ stackWord(context.esp + 4 + UInt32($0.offset) * 4) == $0.element }),
              let storage = heap.lookup(manager, words: 13) else { _ = contextReject(call.function); return nil }
        let capacity = storage[1], table = storage[4], section = manager + 28
        let snapshot = provider.managerSnapshot()
        let block = snapshot.blocks.first(where: { $0.data == table })
        var expected: [UInt32] = []
        var witnessed = true
        switch edge.operation {
        case .tls: witnessed = context.eax == 0 && capacity == 0 && table == 0
        case .initialize, .enter:
            expected = [section]; witnessed = context.eax == section
        case .allocate:
            expected = [0x2002, context.eax]
            witnessed = table == 0 && context.ebp == capacity &+ 32 && context.eax == context.ebp &* 8
        case .handle:
            expected = [table]; witnessed = context.eax == table && block != nil
        case .unlock:
            expected = [context.ebx]; witnessed = block?.handle == context.ebx
        case .reallocate:
            expected = [context.ebx, context.eax, 0x2002]
            witnessed = block?.handle == context.ebx && context.ebp == capacity &+ 32 && context.eax == context.ebp &* 8
        case .failedHandle:
            expected = [table]; witnessed = context.eax == 0 && context.ebx == provider.managerImportTarget(0x5469c4) && stackWord(frame - 8) == 0
        case .failedLock:
            expected = [context.eax]; witnessed = context.eax == (block?.handle ?? 0) && context.ebx == target && stackWord(frame - 8) == 0
        case .failedLeave:
            expected = [section]; witnessed = stackWord(frame - 4) == section && stackWord(frame - 8) == 0
        case .lock:
            expected = [stackWord(frame - 8)]
            witnessed = context.ebx == target && context.eax == expected[0] && snapshot.blocks.contains(where: { $0.handle == expected[0] })
        case .leave:
            expected = [section]; witnessed = validManagerTable(graph) && stackWord(frame - 4) == section && context.eax == context.edi &+ 1 && storage[2] == context.eax
        case .fill:
            expected = [context.eax, 0, context.ecx]
            witnessed = context.ebp == capacity &+ 32 && context.eax == context.ebx &+ capacity &* 8 &&
                context.ecx == (context.ebp &- capacity) &* 8 &&
                provider.ownsSourceBlock(context.ebx, count: context.ebp &* 8) &&
                UInt64(context.eax) + UInt64(context.ecx) == UInt64(context.ebx) + UInt64(context.ebp) * 8
        case .missingThrow:
            witnessed = edge.root == 0x502fb6 ? context.eax == UInt32.max && storage[0] == UInt32.max : stackWord(frame - 8) == 0
        }
        guard witnessed, args == expected else { _ = contextReject(call.function); return nil }
        putStackWord(context.esp, call.sourceReturnPC)
        // Arguments already exist from actual admitted PUSH instructions. They
        // are checked above, never manufactured to rescue a malformed frame.
        let stackBefore = Data(bytes: sourceStack, count: Self.stackSize)
        if edge.operation == .missingThrow || edge.operation == .fill {
            let trace = tlsBegin(graph, function: call.function, pc: call.sourceReturnPC, arguments: args, context: context)
            defer { tlsEnd(graph, trace, context: context, completed: fault == nil) }
            graph.managerEntries.append(.init(function: call.function, returnPC: call.sourceReturnPC,
                arguments: args, context: context, stack: stackBefore, state: snapshot))
            if edge.operation == .missingThrow {
                if (graph.staticApplicationFrame != nil || graph.listOwnedFrame != nil) {
                    _=invokeJointMemoryThrow(graph,call:call,context:&context);pointer.pointee=context
                    graph.managerOutput=context;return nil
                }
                graph.managerOutput = context; graph.tlsOutput = context
                fail(UInt32(CLAW_FAULT_HALT), at: 0x4f50fd, diagnostic: .missingDependency); return nil
            }
            guard let entry = claw_canonical_lookup(call.function)?.pointee,
                  entry.sourceCapability == 2, entry.argumentCount == 3,
                  entry.convention == UInt32(CLAW_CANONICAL_CDECL),
                  entry.sourceInputMask == 0x7ff, entry.sourceOutputMask == 0x7ff, entry.sourcePreserveMask == 0x452 else {
                _ = contextReject(call.function); return nil
            }
            let previous = native.pointee
            frames.append(context.esp); contextEntries.append(call.function)
            native.pointee.entryStackPointer = context.esp; native.pointee.sourceReturnPC = call.sourceReturnPC
            defer {
                frames.removeLast(); contextEntries.removeLast()
                native.pointee.entryStackPointer = previous.entryStackPointer
                native.pointee.sourceContext = previous.sourceContext
                native.pointee.sourceReturnPC = previous.sourceReturnPC
            }
            var eax: UInt32 = 0
            let completed = withUnsafeMutablePointer(to: &context) { child in
                native.pointee.sourceContext = child
                var nested = call; nested.sourceContext = child
                return claw_canonical_dispatch_context(&nested, native, UInt32(CLAW_CANONICAL_SOURCE_GRAPH), &eax) == 1
            }
            guard completed, validManager(graph) else {
                if fault == nil { fail(UInt32(CLAW_FAULT_HOST), at: call.function) }; return nil
            }
            pointer.pointee = context; return eax
        }
        guard provider.managerImportTarget(edge.target) == target else { _ = contextReject(call.function); return nil }
        var observed = context; observed.eip = target
        let physicalTrace = tlsBegin(graph, function: edge.target, pc: call.sourceReturnPC, arguments: args, context: observed, physical: true)
        defer { tlsEnd(graph, physicalTrace, context: context, completed: fault == nil, physical: true) }
        let request = SourceManagerRequest(host: self, graph: graph, provider: provider,
            slot: edge.target, target: target, returnPC: call.sourceReturnPC, arguments: args,
            context: observed, stack: stackBefore)
        defer { request.invalidate() }
        let value = provider.serviceSourceManager(request)
        let stableTable = edge.operation == .enter || edge.operation == .leave || edge.operation == .failedLeave
        let accepted = value != nil && request.validReturn(for: self) && (!stableTable || validManagerTable(graph))
        if !accepted && fault == nil { _ = contextReject(call.function) }
        var output = observed
        if accepted { output.eax = value!; output.esp += 4 + edge.count * 4; output.eip = call.sourceReturnPC }
        graph.managerEvents.append(.init(function: edge.target, target: cached ? target : edge.target,
            importedTarget: target, returnPC: call.sourceReturnPC, arguments: args, result: accepted ? value : nil,
            input: observed, output: output, stackBefore: stackBefore, stackAfter: Data(bytes: sourceStack, count: Self.stackSize),
            before: snapshot, after: provider.managerSnapshot()))
        guard accepted else { graph.managerOutput = observed; graph.tlsOutput = observed; return nil }
        context.eax = output.eax; context.esp = output.esp; context.eip = output.eip
        pointer.pointee = context; return value
    }

    // The admitted constructor calls its owned base/reset bodies directly.
    // The only source callback here is their physical cursor read, carrying the
    // actual root graph and reset-body register/stack witnesses.
    private func callCursorDependency(_ call: ClawCall, graph: SourceGraph, edge: SourceEdge) -> UInt32? {
        guard let service = graph.cursorService, service.valid(for: self),
              contextEntries == [edge.root], edge.caller == edge.root, frames.count == 1,
              let parentPointer = native.pointee.sourceContext, native.pointee.compilerContext == nil,
              let pointer = call.sourceContext, pointer != parentPointer, call.compilerContext == nil,
              edge.target.matches(call.function, allocator: nil), call.sourceReturnPC == edge.continuation,
              call.argumentCount == 1, call.receiver == 0, call.receiver2 == 0,
              call.x87ArgumentCount == 0 else { _ = contextReject(call.function); return nil }
        var context = pointer.pointee
        let parent = parentPointer.pointee, root = frames[0]
        let argument = withUnsafeBytes(of: call.arguments) { $0.loadUnaligned(as: UInt32.self) }
        guard context.size == 72, context.version == 1, context.reserved0 == 0, context.reserved1 == 0,
              context.inputMask == 0x7ff, context.outputMask == 0x7ff, context.preserveMask == 0x472,
              context.eip == call.function, parent.eip == edge.sourceCaller,
              context.esp == parent.esp, call.stackPointer == context.esp,
              validCPU(esp: context.esp, flags: context.eflags, fs: context.fsHead),
              UInt64(context.esp) + UInt64(edge.entryFrameDelta) == UInt64(root),
              context.ebp == root - 4, context.fsHead == root - 16,
              context.eax == service.recordToken + 0x5c, context.ecx == service.recordToken,
              context.esi == service.recordToken, context.edi == 0, context.edx == 0, context.eflags == 0x46,
              argument == context.eax,
              context.eax == parent.eax, context.ebx == parent.ebx, context.ecx == parent.ecx,
              context.edx == parent.edx, context.esi == parent.esi, context.edi == parent.edi,
              context.ebp == parent.ebp, context.eflags == parent.eflags, context.fsHead == parent.fsHead,
              stackWord(context.esp) == call.sourceReturnPC,
              stackWord(context.esp + 4) == argument,
              stackWord(context.esp + 12) == service.recordToken,
              stackWord(context.esp + 16) == 0x50353e,
              stackWord(root) == SourceSite.threadObject.rawValue,
              let allocation = service.allocationSnapshot() else { _ = contextReject(call.function); return nil }
        let observed = context
        let frame = Data(bytes: sourceStack.advanced(by: Int(context.esp - UInt32(CLAW_STACK_BASE))), count: 48)
        let stack = Data(bytes: sourceStack, count: Self.stackSize)
        guard let value = service.perform(host: self) else { _ = contextReject(call.function); return nil }
        context.eax = value; context.esp += 4 + edge.operation.popBytes; context.eip = call.sourceReturnPC
        service.observe(.init(function: call.function, returnPC: call.sourceReturnPC,
            arguments: [argument], context: observed, returnedContext: context,
            frame: frame, stack: stack, allocation: allocation))
        pointer.pointee = context
        return value
    }

    // MARK: - Host lifetime and byte transport

    init(heap: ClawTokenHeap, maximumOperations: UInt32 = 0, dependency: Dependency? = nil) {
        self.heap = heap
        self.dependency = dependency
        native.initialize(to: ClawHost())
        stack.initialize(repeating: 0, count: Self.stackSize)
        sourceStack.initialize(repeating: 0, count: Self.stackSize)
        remainingOperations.initialize(to: 0)
        native.pointee.maximumOperations = maximumOperations
        // The native record borrows this host; the host owns the record and
        // stack buffers through each synchronous entry and callback.
        native.pointee.user = Unmanaged.passUnretained(self).toOpaque()
        native.pointee.bytes = { user, token, count in
            guard let user else { return nil }
            return Unmanaged<ClawNativeCanonicalHost>.fromOpaque(user).takeUnretainedValue()
                .resolveBytes(token, count: count)
        }
        native.pointee.call = { user, call in
            guard let user, let call else { return 0 }
            return Unmanaged<ClawNativeCanonicalHost>.fromOpaque(user).takeUnretainedValue()
                .receiveNativeDependency(call) ?? 0
        }
    }
    deinit {
        native.deinitialize(count: 1)
        native.deallocate()
        stack.deinitialize(count: Self.stackSize)
        stack.deallocate()
        sourceStack.deinitialize(count: Self.stackSize)
        sourceStack.deallocate()
        remainingOperations.deinitialize(count: 1)
        remainingOperations.deallocate()
    }

    var fault: Fault? {
        guard native.pointee.fault != 0 else { return nil }
        let code = native.pointee.fault
        let reason =
            diagnostic
            ?? (code == UInt32(CLAW_FAULT_ABI)
                ? .unsupportedABI : code == UInt32(CLAW_CANONICAL_FAULT_UNKNOWN_ADDRESS) ? .unknownEntry : .nativeFault)
        return Fault(code: code, address: native.pointee.faultAddress, diagnostic: reason)
    }

    // Never clear a preceding fault, including one set directly by native code.
    @discardableResult func fail(_ code: UInt32, at address: UInt32, diagnostic reason: Diagnostic = .nativeFault) -> Fault {
        if native.pointee.fault == 0 {
            native.pointee.fault = code == 0 ? UInt32(CLAW_FAULT_HOST) : code
            native.pointee.faultAddress = address
            diagnostic = reason
        }
        return fault!
    }

    // Exact byte extent, including unaligned interior aliases. Legacy heap
    // snapshot padding is intentionally unavailable to the canonical runtime.
    func bytes(_ token: UInt32, count: UInt32) -> UnsafeMutablePointer<UInt8>? {
        guard fault == nil else { return nil }
        guard activeGraph == nil else {
            fail(UInt32(CLAW_FAULT_ABI), at: token, diagnostic: .unsupportedABI)
            return nil
        }
        return resolveBytes(token, count: count)
    }

    // Only the synchronous native callback and copied SourceGraph operations
    // resolve source memory. The caller cannot retain this private pointer.
    private func resolveBytes(_ token: UInt32, count: UInt32) -> UnsafeMutablePointer<UInt8>? {
        guard fault == nil else { return nil }
        if let graph = activeGraph, !validateGraph(graph, at: token) { return nil }
        let end = UInt64(token) + UInt64(count)
        // The reserved domain never falls through to heap, including empty
        // spans at its upper bound and requests straddling either boundary.
        if (token >= CLAW_STACK_BASE && token <= CLAW_STACK_END) || (token < CLAW_STACK_BASE && end > UInt64(CLAW_STACK_BASE)) {
            guard (!frames.isEmpty || activeGraph != nil), token >= CLAW_STACK_BASE, end <= UInt64(CLAW_STACK_END),
                !heap.overlaps(UInt32(CLAW_STACK_BASE), count: UInt32(Self.stackSize))
            else {
                fail(UInt32(CLAW_FAULT_MEMORY), at: token, diagnostic: .invalidMemorySpan)
                return nil
            }
            let backing = activeGraph == nil ? stack : sourceStack
            return backing.advanced(by: Int(token - UInt32(CLAW_STACK_BASE)))
        }
        guard let pointer = heap.lookupBytes(token, count: count) else {
            fail(UInt32(CLAW_FAULT_MEMORY), at: token, diagnostic: .invalidMemorySpan)
            return nil
        }
        return pointer
    }

    // A recovered noncanonical caller can own the outer synchronous graph.
    // Its source entry ESP and arguments are explicit; descendants must still
    // supply their own entry ESP. Stack aliases survive sibling calls until
    // this body returns. This does not model source return PCs or SEH records.
    func withSourceStackFrame<T>(
        entryStackPointer frame: UInt32, arguments: [UInt32],
        at address: UInt32, body: () -> T
    ) -> T? {
        guard fault == nil else { return nil }
        guard activeGraph == nil else {
            _ = contextReject(address, .recursiveCanonicalCall)
            return nil
        }
        let argumentEnd = UInt64(frame) + 4 * (1 + UInt64(arguments.count))
        guard frames.isEmpty, arguments.count <= Int(CLAW_CALL_ARGUMENT_CAPACITY), frame != 0, frame & 3 == 0,
            frame >= CLAW_STACK_BASE, argumentEnd <= UInt64(CLAW_STACK_END)
        else {
            fail(UInt32(CLAW_FAULT_ABI), at: address, diagnostic: .invalidStackFrame)
            return nil
        }
        guard !heap.overlaps(UInt32(CLAW_STACK_BASE), count: UInt32(Self.stackSize)) else {
            fail(UInt32(CLAW_FAULT_MEMORY), at: UInt32(CLAW_STACK_BASE), diagnostic: .invalidMemorySpan)
            return nil
        }
        let previousFrame = native.pointee.entryStackPointer
        let previousBudget = native.pointee.remainingOperations
        stack.update(repeating: 0, count: Self.stackSize)
        remainingOperations.pointee = native.pointee.maximumOperations == 0 ? 200_000_000 : UInt64(native.pointee.maximumOperations)
        frames.append(frame)
        native.pointee.entryStackPointer = frame
        native.pointee.remainingOperations = remainingOperations
        defer {
            frames.removeLast()
            native.pointee.entryStackPointer = previousFrame
            native.pointee.remainingOperations = previousBudget
        }
