    // x87 transport the generic dependency path accepts: an owned primitive
    // step, or an exact call to a registered entry declared with an x87 result.
    static func isExactX87Transfer(_ call: ClawCall) -> Bool {
        guard call.x87State != nil else { return false }
        if call.x87ArgumentCount == UInt32(CLAW_X87_STEP) { return call.function == 0 }
        guard call.x87ArgumentCount == UInt32(CLAW_X87_EXACT), call.x87Operation == 0,
              let entry = claw_canonical_lookup(call.function) else { return false }
        return entry.pointee.returnKind == UInt32(CLAW_CANONICAL_RETURN_X87) || entry.pointee.x87Environment != 0
    }

